function invertMatrix(a, n){
  var b, i, inva, ipvt, j;
  ipvt = initUnidimensionalArray(I_classLit, $intern_18, 8, n, 15, 1);
  lu_factor(a, n, ipvt);
  b = initUnidimensionalArray(D_classLit, $intern_62, 8, n, 15, 1);
  inva = initMultidimensionalArray(D_classLit, [$intern_3, $intern_62], [12, 8], 15, [n, n], 2);
  for (i = 0; i != n; i++) {
    for (j = 0; j != n; j++)
      b[j] = 0;
    b[i] = 1;
    lu_solve(a, n, ipvt, b);
    for (j = 0; j != n; j++)
      inva[j][i] = b[j];
  }
  for (i = 0; i != n; i++)
    for (j = 0; j != n; j++)
      a[i][j] = inva[i][j];
}

function lu_factor(a, n, ipvt){
  var i, j, k, largest, largestRow, mult, q, row_all_zeros, x_0;
  for (i = 0; i != n; i++) {
    row_all_zeros = true;
    for (j = 0; j != n; j++) {
      if (a[i][j] != 0) {
        row_all_zeros = false;
        break;
      }
    }
    if (row_all_zeros)
      return false;
  }
  for (j = 0; j != n; j++) {
    for (i = 0; i != j; i++) {
      q = a[i][j];
      for (k = 0; k != i; k++)
        q -= a[i][k] * a[k][j];
      a[i][j] = q;
    }
    largest = 0;
    largestRow = -1;
    for (i = j; i != n; i++) {
      q = a[i][j];
      for (k = 0; k != j; k++)
        q -= a[i][k] * a[k][j];
      a[i][j] = q;
      x_0 = $wnd.Math.abs(q);
      if (x_0 >= largest) {
        largest = x_0;
        largestRow = i;
      }
    }
    if (j != largestRow) {
      if (largestRow == -1) {
        console.log('largestRow == -1');
        return false;
      }
      for (k = 0; k != n; k++) {
        x_0 = a[largestRow][k];
        a[largestRow][k] = a[j][k];
        a[j][k] = x_0;
      }
    }
    ipvt[j] = largestRow;
    if (a[j][j] == 0) {
      console.log("didn't avoid zero");
      return false;
    }
    if (j != n - 1) {
      mult = 1 / a[j][j];
      for (i = j + 1; i != n; i++)
        a[i][j] *= mult;
    }
  }
  return true;
}

function lu_solve(a, n, ipvt, b){
  var bi, i, j, row, swap, tot;
  for (i = 0; i != n; i++) {
    row = ipvt[i];
    swap = b[row];
    b[row] = b[i];
    b[i] = swap;
    if (swap != 0)
      break;
  }
  bi = i++;
  for (; i < n; i++) {
    row = ipvt[i];
    tot = b[row];
    b[row] = b[i];
    for (j = bi; j < i; j++)
      tot -= a[i][j] * b[j];
    b[i] = tot;
  }
  for (i = n - 1; i >= 0; i--) {
    tot = b[i];
    for (j = i + 1; j != n; j++)
      tot -= a[i][j] * b[j];
    b[i] = tot / a[i][i];
  }
}

